# Load grids from session and analyze the rule
import os, re, json
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n', '\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

print("Available keys:", sorted(G.keys()))
for k in sorted(G.keys()):
    print(f"\n=== {k} ({len(G[k][0])}x{len(G[k])}) ===")
    if 'input' in k.lower() or k == 'Test input':
        print("INPUT:")
        for i, row in enumerate(G[k]):
            for j, val in enumerate(row):
                marker = "" if val == 0 else f" ({i},{j})"
                print(f"{val} {marker}")
    elif 'output' in k.lower():
        print("OUTPUT:")
        for i, row in enumerate(G[k]):
            for j, val in enumerate(row):
                marker = "" if val == 0 else f" ({i},{j})"
                print(f"{val} {marker}")

# Find all '1' positions in each
def find_ones(grid):
    ones = []
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == 1:
                ones.append((i, j))
    return ones

for k in sorted(G.keys()):
    ones = find_ones(G[k])
    twos_out = []
    if 'output' in k.lower():
        for i in range(len(G[k])):
            for j in range(len(G[k][i])):
                if G[k][i][j] == 2:
                    twos_out.append((i, j))
    print(f"\n{k}: ones={ones}, twos_in_output={twos_out}")

