def build_mirror_sym_grid():
    """Mirror ones around grid center (7): 0→14, 3→11, 6→8"""
    grid = [[0]*15 for _ in range(15)]
    for pos in [0,3,6]:
        grid[pos][pos] = 1
    # Mirror positions as twos
    for pos in [14, 11, 8]:
        grid[pos][pos] = 2
    return json.dumps(grid)

def build_middle_one_twos():
    """Only one two at the MIDDLE available position after last one"""
    grid = [[0]*15 for _ in range(15)]
    for pos in [0,3,6]:
        grid[pos][pos] = 1
    # Single two somewhere... try middle of available space
    grid[10][10] = 2  # Row 10, column 10 (near middle-right)
    return json.dumps(grid)

def build_end_position():
    """Two at very last possible AP position"""
    grid = [[0]*15 for _ in range(15)]
    for pos in [0,3,6]:
        grid[pos][pos] = 1
    grid[14][14] = 2  # Last row/column
    return json.dumps(grid)

